// IN ADVANCE
@Test
public void inAdvancePaymentOfPrincipal() {
    Mockito.when(charges.stream()).thenReturn(Stream.empty());
    Money transactionAmount = ten;
    LoanRepaymentScheduleInstallment installment = Mockito.spy(new LoanRepaymentScheduleInstallment(loan, 1, firstInstallmentToDate, firstInstallmentDueDate, BigDecimal.valueOf(5L), BigDecimal.valueOf(0L), BigDecimal.valueOf(0L), BigDecimal.valueOf(0L), false, null, BigDecimal.ZERO));
    LoanTransaction loanTransaction = Mockito.spy(LoanTransaction.repayment(office, transactionAmount, null, transactionDate, ExternalId.empty()));
    underTest.handleTransactionThatIsPaymentInAdvanceOfInstallment(installment, null, loanTransaction, transactionAmount, transactionMappings, charges);
    // Calculated zero
    Mockito.verify(installment, Mockito.times(1)).payPenaltyChargesComponent(eq(transactionDate), refEq(zero));
    // Calculated zero
